architecture.h4_f:
msg = CBOR{v:1, text, reply_to, send_at}
ct = AES-GCM-256-Encrypt(k, nonce, msg, aad=room_id)
POST /api/rooms/{id}/messages {ciphertext: hex(ct), nonce: hex}

cryptoWire.h1_f:
pt = CBOR{v:1, text, reply_to?, thread_id?, mentions?, sent_at}
ct = AES-GCM-256-Encrypt(room_key, nonce, pt, aad=hex(room_id))
fir = CBOR{
  v: 1,
  text cifrat: hex(ct), // lungime variabilă
  nonce: hex(12 B),
  sender_pseudo: hex(16 B),
  sent_at: unix_ms
}

cryptoWire.h5_f:
exterior = CBOR{
  nod_sursă: hex32,
  utilizator_țintă: int64,
  text_cifrat interior: octeți,
  inner_nonce: octeți,
  sent_at: unix_ms
}
sig = Ed25519-Sign(source_priv, outer)
POST /federation/deliver { plic: exterior, semn: hex64 }

auth.h1_f:
POST /api/authentication/register
  { nume de utilizator, parolă, x25519_public_key, display_name, telefon?, e-mail?, avatar_emoji }

Răspunsul 201 Creat:
  { access_token, refresh_token, user_id, username, ... }

auth.h3_f:
sarcină utilă access_token:
  { sub: user_id, jti: device_id, typ: „access”, exp: acum + 15min }
sarcină utilă refresh_token:
  { sub: user_id, jti: device_id, typ: „refresh”, exp: acum + 30d }

HS256-semnat cu secretul de 64 de octeți al nodului din .env

auth.h4_f:
register_begin(): provocare = rand(32)
                    opțiuni = { rp.id, user.id, pubKeyCredParams, challenge }
                    opțiuni de returnare

register_finish(atestare):
  verificați atestarea împotriva TPM / Secure Enclave root CA
  stocați { credential_id, public_key, counter: 0 }

auth.h7_f:
POST /api/authentication/qr/begin
  → { nonce: hex pe 128 de biți, ttl: 60 }
QR sarcină utilă = { nonce, user_id, server: "https://node.example" }

POST /api/authentication/qr/verify { nonce }
  → dispozitiv nou înregistrat; JWT-urile s-au întors.

rooms.h6_f:
sender_pseudo = HMAC-SHA256(room_pseudo_salt, sender_id)[:16] // 32 hex
ciphertext = AES-GCM-Encrypt(room_key, nonce, CBOR_payload, aad=room_id)

Cadru extins: { type:"m", room, msg:{id, ct, nonce, sender_pseudo, sent_at} }

files.h2_f:
init POST /api/files/resumable/init {filename, size, chunk_size_hint}
            ← {upload_id, chunk_size}
chunk PUT /api/files/resumable/{upload_id}/chunk/{offset} <ct bytes>
            ← 204
finaliza POST /api/files/resumable/{upload_id}/finalise {plain_blake3}
            ← 201 {file_id, url}
TTL pe neterminat: 24 h

files.h4_f:
deny_list = {
  "application/x-dosexec",
  "application/x-sharedlib",
  "aplicație/x-mach-binary",
}
dacă magic.from_buffer(buf[:1024]) în deny_list: returnează 415

presence.h1_f:
client: la prima apăsare a tastei → trimite {type:"t", state:"start"}
         nu mai trimite timp de 3 s decât dacă starea se schimbă
         10 s după ultima apăsare a tastei → trimite {type:"t", state:"stop"}
receptor: oprire automată la 10 s după ultimul „pornire” dacă nu a sosit niciun „oprire”.

calls.h1_f:
POST /api/calls/{room_id}/start {video, audio} → call_id
WS difuzați {type:"c", kind:"invite", call_id}
WS difuzare {tip:"c", fel:"ofertă", sdp}
WS difuzare {tip:"c", fel:"răspuns", sdp}
WS difuzare {tip:"c", fel:"candidat",ice} × N
POST /api/calls/{call_id}/end

federation.h2_f:
plic = {
  nod_sursă: hex32,
  utilizator_țintă: int64,
  text_cifrat interior: octeți,
  inner_nonce : octeți,
  sent_at : unix_ms,
}
sig = Ed25519Sign(source_priv, CBOR(plic))
POST /federation/deliver { plic, semn }

gossip.h3_f:
publicitate = {pubkey, endpoint, advertised_at}
sig = Ed25519-Sign(pubkey_priv, CBOR(publicitate))
sarcină utilă de bârfă: [..., {ad, sig}, ...]

receptor: verificați semnul față de ad.pubkey → stocați dacă este ok
suplimentar: PoW de 2^18 zerouri de început pe {pubkey, endpoint}

stealth.h2_f:
ClientHello bytes = chrome_120_template cu {
  aleatoriu = aleatoriu nostru,
  server_name = numele nostru de gazdă (sau ECH-wrapped),
  session_id = ID-ul sesiunii noastre,
}
JA4 = t13d_xxxx_xxxx_xxxx (se potrivește cu stabilul Chrome actual)

stealth.h4_f:
DoH: POST https://cloudflare-dns.com/dns-query {nume: x.vortexx.sol}
ECH: ClientHello.extensions += encrypted_sni(public_key_from_HTTPS_record)
DGA: domain(t) = base32( SHA256(seed ∥ YYYY-MM-DD) )[:16] + „.example”

push.h4_f:
iOS NSE: didReceive(request) { decrypt(request.content.userInfo) }
Android FCM: onMessageReceived(remoteMessage) { decrypt(remoteMessage.data) }
Web SW: self.addEventListener('push', e => decrypt(e.data))

controller.h2_f:
instrument = instrument_semn
input = arborele sursă, keys/release.key
manifest = {
  versiunea: "0.1.0",
  built_at: unix_ms,
  fișiere: [{cale, sha256, dimensiune}, ...]
}
sig = Ed25519-Sign(release_priv, CBOR(manifest))
output = INTEGRITY.sig.json = {manifest, signed_by: pub_hex, sig: sig_hex}

bots.h1_f:
creați: POST /api/bots {username, display_name, code}
          → {bot_id, token, pubkey}
rulare: în proces (corutină în interiorul nodului)
      OR extern (long-poll /api/bots/{id}/updates, token-auth'd)
mesaj: {text, semnătură: Ed25519-Sign(bot_priv, canonical_msg)}

